import json, pathlib, re, html
S=open('scratchpad/CURRENT').read().strip(); d=pathlib.Path(f'retrieval-log/{S}')
recs=[json.loads(l) for l in (d/'manifest.jsonl').read_text().splitlines() if l.strip()]
for r in recs:
    p=r.get('purpose',''); tag=p[:2]
    if tag not in ('T5','T6','T7','W5','W6'): continue
    raw=(d/r['artefact']).read_text(errors='replace')
    print(f"\n{'='*70}\n{tag}: {p[3:80]}\n{'='*70}")
    if tag=='T5':
        # TRID results page: pull record titles
        titles=re.findall(r'<a[^>]+href="/view/(\d+)"[^>]*>(.*?)</a>', raw, re.S|re.I)
        if not titles:
            titles=re.findall(r'href="/View/(\d+)"[^>]*>\s*(.*?)\s*</a>', raw, re.S|re.I)
        print(f"  records found on page: {len(titles)}")
        for i,(rid,t) in enumerate(titles[:15]):
            print(f"   {rid}: {html.unescape(re.sub('<[^>]+>','',t)).strip()[:85]}")
        m=re.search(r'([\d,]+)\s*(?:results|records)', raw, re.I)
        print("  result-count text:", m.group(0) if m else "not found")
        if 'Just a moment' in raw or 'cf-browser' in raw: print("  !! Cloudflare interstitial")
    elif tag=='T6':
        doc=json.loads(raw); msg=doc['message']
        print(f"  total-results: {msg['total-results']}")
        for it in msg['items'][:5]:
            au=", ".join(f"{a.get('family','')}" for a in it.get('author',[]))[:40]
            print(f"   {it.get('issued',{}).get('date-parts',[['?']])[0][0]} | {au:40} | {(it.get('title') or ['?'])[0][:65]}")
    elif tag=='T7':
        print("  ", raw[:300])
    else:
        doc=json.loads(raw)
        if tag=='W5':
            rr=doc.get('response',{})
            print(f"  numFound: {rr.get('numFound')}")
            for x in rr.get('docs',[])[:15]: print("   ", x)
        else:
            print(f"  numFound: {doc.get('numFound')}")
            for x in doc.get('docs',[])[:15]: print("   ", x)
