import json, pathlib, re, html
S=open('scratchpad/CURRENT').read().strip(); d=pathlib.Path(f'retrieval-log/{S}')
recs=[json.loads(l) for l in (d/'manifest.jsonl').read_text().splitlines() if l.strip()]
for r in recs:
    p=r.get('purpose','')
    if p.startswith('T5'):
        raw=(d/r['artefact']).read_text(errors='replace')
        # TRID markup: find result blocks
        for m in re.finditer(r'href="(/[Vv]iew/\d+)"[^>]*>(.{0,200}?)</a>', raw, re.S):
            t=html.unescape(re.sub('<[^>]+>','',m.group(2))).strip()
            if t: print(f"  TRID {m.group(1)}: {t[:95]}")
